use std::fmt;
use std::iter::Sum;
use std::ops::{Add, Mul, Neg, Sub};
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default)]
struct Money(i64);

impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let sign = if self.0 < 0 { "-" } else { "" };
        let c = self.0.unsigned_abs();
        write!(f, "{sign}{}.{:02}", c / 100, c % 100)
    }
}

impl FromStr for Money {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let s = s.trim();
        let (negative, digits) = match s.strip_prefix('-') {
            Some(rest) => (true, rest),
            None => (false, s.strip_prefix('+').unwrap_or(s)),
        };
        let (whole, frac) = digits.split_once('.').unwrap_or((digits, ""));
        if !all_digits(whole) || (digits.contains('.') && !all_digits(frac)) || frac.len() > 2 {
            return Err(format!("not an amount: '{s}'"));
        }
        let whole: i64 = whole.parse().map_err(|_| format!("too large: '{s}'"))?;
        let frac: i64 = match frac.len() {
            0 => 0,
            1 => frac.parse::<i64>().unwrap() * 10,
            _ => frac.parse().unwrap(),
        };
        let cents = whole.checked_mul(100).and_then(|c| c.checked_add(frac)).ok_or(format!("too large: '{s}'"))?;
        Ok(Money(if negative { -cents } else { cents }))
    }
}

fn all_digits(t: &str) -> bool {
    if t.is_empty() {
        return false;
    }
    for c in t.chars() {
        if !c.is_ascii_digit() {
            return false;
        }
    }
    true
}

impl Add for Money {
    type Output = Money;
    fn add(self, o: Money) -> Money { Money(self.0 + o.0) }
}

impl Sub for Money {
    type Output = Money;
    fn sub(self, o: Money) -> Money { Money(self.0 - o.0) }
}

impl Mul<i64> for Money {
    type Output = Money;
    fn mul(self, k: i64) -> Money { Money(self.0 * k) }
}

impl Neg for Money {
    type Output = Money;
    fn neg(self) -> Money { Money(-self.0) }
}

impl Sum for Money {
    fn sum<I: Iterator<Item = Money>>(iter: I) -> Money {
        let mut total = Money(0);
        for m in iter {
            total = total + m;
        }
        total
    }
}

impl From<i64> for Money {
    fn from(euros: i64) -> Money { Money(euros * 100) }
}

unitTests:
test("display", || {
    check_eq(Money(1234).to_string(), "12.34");
    check_eq(Money(-5).to_string(), "-0.05");
    check_eq(Money(100_000).to_string(), "1000.00");
    check_eq(Money::default().to_string(), "0.00");
    check_eq(format!("[{:>8}]", Money(250).to_string()), "[    2.50]");
});

test("parsing", || {
    check_eq("12.34".parse::<Money>(), Ok(Money(1234)));
    check_eq("-5".parse::<Money>(), Ok(Money(-500)));
    check_eq("0.5".parse::<Money>(), Ok(Money(50)));
    check_eq(" +3.10 ".parse::<Money>(), Ok(Money(310)));
    for bad in ["", "1.234", "abc", "1.", ".5", "1,50", "--1", "99999999999999999999"] {
        check(bad.parse::<Money>().is_err());
    }
});

test("arithmetic", || {
    let tea = Money(250);
    let cake = Money::from(4);
    check_eq(tea + cake, Money(650));
    check_eq(cake - tea * 2, Money(-100));
    check_eq(-tea, Money(-250));
    let total: Money = vec![tea, cake, Money(1)].into_iter().sum();
    check_eq(total, Money(651));
});

test("ordering and hashing", || {
    let mut prices = vec![Money(300), Money(-20), Money(150)];
    prices.sort();
    check_eq(prices.clone(), vec![Money(-20), Money(150), Money(300)]);
    check_eq(prices.iter().max(), Some(&Money(300)));
    let set: std::collections::HashSet<Money> = [Money(1), Money(1), Money(2)].into_iter().collect();
    check_eq(set.len(), 2);
});

